import {survivalPackPage} from './survival-pack-ui.js';
import {survivalPackView} from './survival-pack.js';
import {survivalExplorationPage} from './survival-exploration-ui.js';
import {campIncidentView,campPendingView} from './camp-incidents.js';
import {renderShelterScene} from './shelter-scene.js';
import {survivalSites,survivalFacilities,survivalJobs,survivalCompanions,survivalMemberName,survivalDefense,survivalNightRisk,survivalDayPreview} from './survival-base.js';
import {displayName} from './identity.js';
const shelterEsc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function shelterButton(label,action,value='',disabled=false){return `<button data-action="${action}" data-value="${value}" ${disabled?'disabled':''}>${label}</button>`;}
function shelterResource(name,value){return `<span><small>${name}</small><b>${value}</b></span>`;}
export function survivalPage(state,tab='overview',error='',selectedFacility='',exploreBuilding='arts',exploreFloor=''){
 const r=state.survivalRun,head=`<header class="shelter-header"><div><small>CAMPUS / SURVIVAL</small><h1>${r?.base?survivalSites[r.base.site].name:'돌아올 곳을 찾아서'}</h1></div><div>${shelterButton('저장 · 메뉴','openQuick')}${shelterButton('학교생활 메뉴','survivalExit')}</div></header>`;
 if(!r)return `<section class="shelter-shell">${head}<article class="shelter-intro"><span class="shelter-kicker">도주에서 거점 생활로</span><h2>첫날에는, 돌아갈 곳이 없다.</h2><p>초반 이틀은 도주로를 넘으며 식량과 물을 지킨다. 사흘째부터 건물과 방을 직접 돌아보며 감염체가 없는 공간을 찾고, 동료와 돌아올 거점을 만든다.</p><ol><li>초반 도주 · 숨기 / 주변 물자 챙기기 / 실제 탈출 전투</li><li>건물·층 탐색 · 빈 방 확인 또는 감염체 제압 · 출입문 정리</li><li>거점 운영 · 시설 설치 / 역할 배치 / 보급과 구조 원정</li></ol><label>이번 생존 흐름에서 함께할 동료<select id="survival-companion">${survivalCompanions(state).map(id=>`<option value="${id}">${id==='student'?'이름 모르는 학생':shelterEsc(displayName(state,id))}</option>`).join('')}</select></label><p class="shelter-note">학교생활 이후를 시험하는 별도 생존 흐름입니다. 학교의 날짜·관계·돈·소지품과 전투 체험 보관함을 덮어쓰지 않아요. 동행 선택은 이 흐름에만 적용됩니다.</p>${shelterButton('사태 첫날부터 시작','survivalStart')}</article></section>`;
 const preview=survivalDayPreview(state),incident=campIncidentView(state);
 const pack=survivalPackView(state),busy=!!r.activeSortie,site=r.base?survivalSites[r.base.site]:null,fields=r.base?r.base.facilities:[],resources={...r.resources,...(busy&&!state.combatTrial?.survivalPack?state.combatTrial?.stash?.items??{}:{})},risk=survivalNightRisk(r),stage=r.stage==='base'?'거점 생활':r.stage==='settlement'?'거점 후보 확보':'도주 생활';
 const top=`<section class="shelter-status"><div><b>사태 ${r.day}일차</b><span>${stage} · 행동 여력 ${r.actions}/3${busy?' · 원정 진행 중':''}</span></div><div><span>주변 위협 ${r.threat}/100</span><span>${r.base?'문 상태 '+r.base.integrity+'/100 · 방어 '+survivalDefense(r):'도주로 통과 '+r.escapes+'/2'}</span></div></section><div class="shelter-resources">${shelterResource('식량',resources.food)}${shelterResource('생수',resources.water)}${shelterResource('붕대',resources.bandage)}${shelterResource('부품',resources.parts)}<small>${busy?'공동 보관량 · 가방 물품은 전투 화면에서 확인':'하루 배급 · 식량 '+r.members.length+' / 생수 '+r.members.length}</small>${!busy&&pack?.initialized?`<small>가방·통조림 포함 배급 가능량 · 식량 ${pack.rationFood} / 생수 ${pack.rationWater}</small>`:''}</div><nav class="shelter-tabs">${[['overview','생활·원정'],['base','거점·시설'],['people','인원·역할'],['bag','가방·물자'],['journal','생존 기록']].map(([id,label])=>`<button data-action="survivalTab" data-value="${id}" aria-pressed="${tab===id}">${label}</button>`).join('')}</nav>`;
 let body='';
 if(tab==='bag'&&!busy)body=survivalPackPage(state);
 else if(busy){const done=state.combatTrial?.status!=='active';body=`<article class="shelter-away"><h2>${done?'작전 결과를 확인하고 복귀할 수 있어요':'밖에서 작전이 진행 중이에요'}</h2><p>복귀 전에는 거점 공사·배급·역할 변경을 진행하지 않아요. 전리품과 남은 휴대 물자는 복귀할 때 창고에 반영됩니다.</p>${done&&state.combatTrial?.survivalPack?.pending?shelterButton('복귀 전 발견 물자 확인','survivalResume'):''}${done?shelterButton(state.combatTrial?.survivalPack?.pending?'남은 물자 두고 · 복귀':'작전 결과 반영 · 복귀','survivalReturn'):shelterButton('작전으로 돌아가기','survivalResume')}${!done?shelterButton('작전 중단 · 실패로 복귀','survivalAbort'):''}</article>`;}
 else if(r.status!=='active')body=`<article class="shelter-away"><h2>이번 생존 기록은 여기까지</h2><p>배급 부족이나 위협을 감당하지 못했어요. 이전 저장을 불러오거나 생존 기록만 새로 시작할 수 있어요.</p>${shelterButton('새 생존 기록 시작 · 현재 기록 초기화','survivalRestart')}</article>`;
 else if(tab==='overview')body=`<div class="shelter-columns"><article class="shelter-card"><h2>${r.base?'오늘의 생활':'오늘을 버티는 방법'}</h2><div class="shelter-actions">${shelterButton('몸을 숨기고 쉬기 · 여력 1','survivalAction','hide',r.actions<1)}${shelterButton(r.searchDay===r.day?'오늘의 주변 물자 수색 완료':'주변 물자 수색 · 여력 1','survivalAction','search',r.actions<1||r.searchDay===r.day)}${shelterButton('응급처치 · 붕대 1, 여력 1','survivalAction','treat',r.actions<1||r.resources.bandage<1||!r.members.some(m=>m.injury>0))}</div><p>${r.base?'안전한 밤도 준비가 필요해요. 시설과 감시 인원을 살펴보세요.':'사흘째부터, 도주로를 두 번 통과한 기록이 있으면 빈 강의실을 알아볼 수 있어요.'}</p></article><article class="shelter-card"><h2>${r.stage==='flight'?'오늘의 도주':'밖에서 해야 할 일'}</h2><div class="shelter-actions">${r.stage==='flight'?shelterButton('동료와 도주로 통과 · 탈출 전투','survivalSortie','escape',r.actions<1):r.base?shelterButton('식량 보급 · 제압 임무','survivalSortie','supply',r.actions<1)+shelterButton('부상 학생 구조 · 보호 임무','survivalSortie','rescue',r.actions<1||r.members.length>=site.capacity)+shelterButton('거점 주변 방어 · 보호 임무','survivalSortie','defend',r.actions<1):'<p>거점·시설 탭의 지도에서 건물과 층을 고르고 빈 공간을 찾아보세요.</p>'}</div><p>원정 시작은 행동 여력 1을 사용해요. 가방·물자 탭에서 챙긴 물품만 휴대해요. 전투에서 실제로 성공해야 확보·구조·보급이 반영돼요.</p></article></div><article class="shelter-night"><div><h2>하루를 마무리하면</h2><p>인원수에 맞게 식량과 물을 나누고, 피로·시설·야간 위협을 정산해요.</p><strong>${r.base?risk>=25?'야간 침입 위험 높음 · 감시/보강 필요':'야간 침입 위험 낮음':'머무를 거점 없음 · 밤의 피로가 더 쌓임'}</strong></div>${shelterButton('배급하고 다음 날로','survivalNextDay','',r.stage==='flight'&&r.escapes<Math.min(2,r.day)||!!r.kit?.pending)}</article>`;
 else if(tab==='base'){
  if(!r.base)body=survivalExplorationPage(state,exploreBuilding,exploreFloor);
  else body=`<div class="shelter-visual-layout">${renderShelterScene(r,selectedFacility)}<article class="shelter-card"><h2>시설 설치 · 여력 1</h2><div class="shelter-facilities">${Object.entries(survivalFacilities).map(([id,f])=>`<div><strong>${f.name}</strong><p>${f.effect} · 부품 ${f.cost}</p>${shelterButton(fields.includes(id)?'설치됨':fields.length>=site.slots?'시설 공간 부족':r.resources.parts<f.cost?'부품 부족':'설치하기','survivalBuild',id,fields.includes(id)||fields.length>=site.slots||r.resources.parts<f.cost||r.actions<1)}</div>`).join('')}</div></article></div>`;
 }else if(tab==='people')body=`<article class="shelter-card"><h2>함께 살아남을 사람들 · ${r.members.length}${site?'/'+site.capacity:''}명</h2><p>전공으로 역할을 제한하지 않아요. 너무 지친 사람은 쉬어야 해요. 밤에 맡은 역할이 반영됩니다.</p><div class="shelter-people">${r.members.map(m=>`<article><div><strong>${shelterEsc(survivalMemberName(state,m))}</strong><p>피로 ${m.fatigue} · 부담 ${m.stress} · 부상 ${m.injury}</p></div><label>역할<select id="survival-role-${m.key}">${Object.entries(survivalJobs).map(([id,label])=>`<option value="${id}" ${m.job===id?'selected':''} ${id==='care'&&!fields.includes('clinic')||id==='repair'&&!fields.includes('workshop')?'disabled':''}>${label}</option>`).join('')}</select></label>${shelterButton('역할 적용','survivalAssign',m.key,!r.base)}</article>`).join('')}</div>${!r.base?'<p>거점을 확보한 뒤 역할을 나눌 수 있어요.</p>':''}</article>`;
 else body=`<article class="shelter-card"><h2>생존 기록</h2>${r.history.slice().reverse().map(h=>`<p><small>사태 ${h.day}일차</small> · ${shelterEsc(h.text)}</p>`).join('')||'<p>첫날의 기록이 막 시작됐어요.</p>'}</article>`;
 if(tab==='overview'&&!busy&&r.status==='active'){
  const labels={food:'식량',water:'생수',parts:'부품',bandage:'붕대',actions:'여력'};
  const incidentPanel=r.base?(incident?`<article class="camp-incident" aria-label="오늘 거점의 상황"><span class="shelter-kicker">오늘 여기서 · 선택은 내일에도 이어져요</span><h2>${shelterEsc(incident.title)}</h2><p>${shelterEsc(incident.text)}</p><div class="camp-choices">${incident.choices.map(c=>`<button data-action="survivalIncident" data-value="${c.id}" ${c.blocked?'disabled':''}><strong>${shelterEsc(c.label)}</strong><small class="camp-cost">${Object.entries(c.cost).map(([k,v])=>labels[k]+' −'+v).join(' · ')||'소비 없음'}</small><small>${shelterEsc(c.effect)}</small>${c.blocked?`<small>${shelterEsc(c.blocked)}</small>`:''}</button>`).join('')}</div>${shelterButton('지금은 개입하지 않는다 · 소비 없음','survivalIncident','pass')}<p class="shelter-note">결정하지 않고 하루를 마쳐도 추가 불이익은 없어요.</p></article>`:r.story?.checkedDay!==r.day?`<article class="camp-incident"><h2>오늘 주변은 어떨까</h2>${shelterButton('거점 주변 상황 살펴보기 · 소비 없음','survivalCheck')}</article>`:''):'';
  const pending=campPendingView(state),next=preview.canFinish?`<section class="camp-night-preview" aria-label="오늘 밤 예상 결과"><h2>이대로 밤을 보내면</h2><div>${['food','water','bandage','parts'].map(k=>`<p><small>${labels[k]}</small><strong>${r.resources[k]} → ${preview.after[k]}</strong></p>`).join('')}</div><p>위협 ${preview.nextThreat}/100${preview.nextIntegrity!==null?' · 문 상태 '+preview.nextIntegrity+'/100':''}${preview.short?' · 배급 부족':''}</p>${preview.failed?'<strong class="camp-danger">이대로 진행하면 생존 기록이 끝나요. 물자·위협·문 상태를 먼저 확인하세요.</strong>':''}${pending.map(p=>`<p class="camp-followup">내일 이어질 일 · ${shelterEsc(p.title)}: ${shelterEsc(p.effect)}</p>`).join('')}<small>현재 물자·역할·확정된 후속 결과 기준. 다른 행동을 하면 다시 계산돼요.</small></section>`:`<p class="shelter-note">${shelterEsc(preview.reason)}</p>`;
  const report=r.lastNight?`<details class="camp-night-report"><summary>지난밤 돌아보기 · 사태 ${r.lastNight.day}일차</summary>${r.lastNight.events.map(e=>`<p>${shelterEsc(e)}</p>`).join('')}</details>`:'';
  body=(r.base?renderShelterScene(r,selectedFacility,true):'')+incidentPanel+report+body+next;
 }

 return `<section class="shelter-shell">${head}${top}${error?`<p class="shelter-error" role="alert">${shelterEsc(error)}</p>`:''}<section class="shelter-last" aria-live="polite">${shelterEsc(r.log.join(' '))}</section>${pack&&!busy&&tab!=='bag'?`<aside class="pack-shortcut"><span>${pack.stats.name} · ${pack.stats.usedSlots}/${pack.stats.slots}칸 · ${(pack.stats.weight/1000).toFixed(2)}kg${pack.pending?' · 발견 물자 정리 필요':''}</span>${shelterButton(pack.pending?'발견 물자 확인':'가방 열기','survivalTab','bag')}</aside>`:''}${body}<p class="shelter-note">생존 흐름 시제품 · 학교생활 기록과 분리됩니다. 탐색 가능한 16개 공간의 상태는 플레이마다 달라져요. 제압 전투 배치는 아직 공통 보드를 사용해요.</p></section>`;
}
